export function validateLabPose(p,safe){if(p===null)return true;if(!p||![Object.prototype,null].includes(Object.getPrototypeOf(p))||Reflect.ownKeys(p).length!==keys.length)return false;const r={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(p,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))return false;r[k]=d.value}if(r.sceneId!==C.sceneId||r.imageSHA!==C.assets['assets/room.png']||r.maskSHA!==C.assets['assets/lab.safe.u8']||!['up','down','left','right'].includes(r.facing)||typeof r.released!=='boolean'||typeof r.left!=='boolean'||!Array.isArray(r.foot)||Object.getPrototypeOf(r.foot)!==Array.prototype||Reflect.ownKeys(r.foot).length!==3)return false;const a=Object.getOwnPropertyDescriptor(r.foot,'0'),b=Object.getOwnPropertyDescriptor(r.foot,'1');if(!a||!b||!Object.hasOwn(a,'value')||!Object.hasOwn(b,'value'))return false;const x=a.value,y=b.value;return Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&x<960&&y>=0&&y<640&&safe[y*960+x]===1&&(Math.abs(x-470)>48||Math.abs(y-265)>36)}
